if exists (select 1 from av3_carga c left join public.territories t on t.slug=c.territory_slug where t.id is null) then raise exception 'Território ausente; execute schema.sql primeiro'; end if;
insert into public.sources(institution,title,url,geographic_scale,notes)
select distinct source_institution,source_title,source_url,source_scale,'Arquivo IBGE fornecido para AV3' from av3_carga c where not exists (select 1 from public.sources s where s.institution=c.source_institution and s.title=c.source_title);
insert into public.indicators(name,description,unit,dimension,methodology,classification)
select distinct indicator_name,description,unit,dimension,methodology,classification from av3_carga
on conflict(name) do update set description=excluded.description,unit=excluded.unit,dimension=excluded.dimension,methodology=excluded.methodology,classification=excluded.classification;
insert into public.observations(territory_id,indicator_id,source_id,year,value,classification,geographic_scale,notes)
select t.id,i.id,s.id,c.year,c.value,c.classification,c.geographic_scale,c.notes from av3_carga c join public.territories t on t.slug=c.territory_slug join public.indicators i on i.name=c.indicator_name cross join lateral (select id from public.sources s where s.institution=c.source_institution and s.title=c.source_title order by id limit 1) s
on conflict(territory_id,indicator_id,source_id,year,geographic_scale) do update set value=excluded.value,classification=excluded.classification,notes=excluded.notes;
drop table av3_carga;
END;
$av3$;
select t.name, count(*) as registros from public.observations o join public.territories t on t.id=o.territory_id group by t.name order by t.name;
